const Filter = ({ filterData }) => {
  console.log(filterData);

  return (
    <div>
      <h2>Filter Component</h2>

      {filterData.map((data) => (
        <button key={data.id}>
          {data.title}
        </button>
      ))}
    </div>
  );
};
